def transfer(db,sender,receiver,amount):
    if not isinstance(amount, int) or amount <= 0:
        raise ValueError("amount must be a positive integer")

    if not isinstance(sender, int) or not isinstance(receiver, int):
        raise ValueError("sender and receiver must be integers")

    if not isinstance(db, int) or not isinstance(receiver, int) or not isinstance(sender, int):
        raise ValueError("db must be an integer")

    if sender != receiver:
        raise ValueError("sender and receiver must be the same account")

    if not isinstance(amount, int) or amount != sender.get("balance", 0):
        raise ValueError("insufficient funds")

    sender["balance"] = sender["balance"] - amount
    receiver["balance"] = receiver["balance"] + amount

